import { apiClient } from '../api';
import { BffResponse, unwrap } from '../shared/bffEnvelope';

export interface FileInitRequest {
  purpose: string;
  product: string;
  entityType?: string;
  entityId?: string;
  fileName: string;
  contentType: string;
  sizeBytes: number;
}

export interface FileInitResponse {
  uploadId: string;
  objectKey: string;
  uploadUrl: string;
  method: string;
  requiredHeaders?: Record<string, string>;
  expiresAt: string;
  storageKind: string;
}

export interface FileCommitRequest {
  uploadId: string;
  entityType?: string;
  entityId?: string;
  replaceAttachmentId?: string;
}

export interface FileAttachmentResponse {
  attachmentId: string;
  uploadId: string;
  objectKey: string;
  fileName: string;
  contentType: string;
  sizeBytes: number;
}

export interface FileUrlResponse {
  attachmentId: string;
  url: string;
  expiresAt: string;
}

export const filesEndpoint = {
  init: async (body: FileInitRequest): Promise<FileInitResponse> => {
    const res = await apiClient.post<BffResponse<FileInitResponse>>('/files/init', body);
    return unwrap(res);
  },

  complete: async (uploadId: string, objectKey: string): Promise<void> => {
    await apiClient.post('/files/complete', { uploadId, objectKey });
  },

  commit: async (body: FileCommitRequest): Promise<FileAttachmentResponse> => {
    const res = await apiClient.post<BffResponse<FileAttachmentResponse>>('/files/commit', body);
    return unwrap(res);
  },

  abort: async (uploadId: string): Promise<void> => {
    await apiClient.post('/files/abort', { uploadId });
  },

  getUrl: async (attachmentId: string): Promise<FileUrlResponse> => {
    const res = await apiClient.get<BffResponse<FileUrlResponse>>(`/files/${attachmentId}/url`);
    return unwrap(res);
  },

  getObject: async (attachmentId: string): Promise<Blob> => {
    try {
      return await apiClient.getBlob(`/files/${attachmentId}/object`);
    } catch (err) {
      const status = err && typeof err === 'object' && 'statusCode' in err
        ? Number((err as { statusCode?: number }).statusCode)
        : undefined;
      const code = err && typeof err === 'object' && 'errorCode' in err
        ? String((err as { errorCode?: string }).errorCode || '')
        : '';
      if (
        status === 404
        || code === 'FILE_OBJECT_GONE'
        || code === 'FILE_OBJECT_MISSING'
        || code === 'FILE_ATTACHMENT_NOT_FOUND'
      ) {
        const raw = err instanceof Error ? err.message.trim() : '';
        throw Object.assign(new Error(raw || 'Chưa tìm thấy file trên storage (chưa PUT hoặc đã xóa).'), {
          statusCode: status ?? 404,
          errorCode: code || 'FILE_OBJECT_MISSING',
        });
      }
      throw err;
    }
  },

  getObjectPreviewUrl: async (attachmentId: string): Promise<string> => {
    const blob = await filesEndpoint.getObject(attachmentId);
    return URL.createObjectURL(blob);
  },
};
